#!/usr/bin/env bash
set -euo pipefail
root="$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)"
repo="$(CDPATH= cd -- "$root/.." && pwd)"
bun="${BUN:-$HOME/.local/bin/bun}"
if [[ ! -x "$bun" ]]; then bun="$(command -v bun)"; fi
version="$(sed -n '/^\[package\]/,/^\[/{s/^version *= *"\(.*\)"/\1/p}' "$repo/Cargo.toml" | head -1)"
[ -n "$version" ] || { echo "build: could not read version from Cargo.toml" >&2; exit 1; }
suffix="-dev"
if [[ "${NEUTRONSYNC_RELEASE_BUILD:-}" == "1" ]]; then
	suffix=""
fi
drive_version="${version}${suffix}"
cat >"$root/src/build-version.ts" <<EOF
/** Generated by sidecar/build.sh from the Cargo.toml version; do not edit by hand. */
export const neutronsyncDriveVersion = '${drive_version}';
EOF
mkdir -p "$root/dist"
"$bun" build --compile --target=bun-linux-x64 --no-compile-autoload-dotenv --no-compile-autoload-bunfig \
  --asset="$root/node_modules/@protontech/drive-sdk/dist/search/vendor/proton_drive_sdk_search_bg.wasm" \
  "$root/src/main.ts" --outfile "$root/dist/neutronsync-drive"
if [[ "${NEUTRONSYNC_RELEASE_BUILD:-}" == "1" ]]; then
	if grep -q '\-dev' "$root/src/build-version.ts"; then
		echo "build: release build-version still has a -dev suffix" >&2
		exit 1
	fi
	expected_line="export const neutronsyncDriveVersion = '${version}';"
	if ! grep -qF "$expected_line" "$root/src/build-version.ts"; then
		echo "build: expected ${expected_line} in build-version.ts" >&2
		exit 1
	fi
fi
